window.TEXTP["49.9"] = [[["p","610 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 609]."],["p","611 ― [Под этим номером приведён похожий хадис со слов Абу Са′ида аль-Худри (да будет доволен им Аллах)]."],["p","ГЛАВА 63: УПОМИНАНИЕ ТОГО, ЧТО ВСЕВЫШНИЙ АЛЛАХ БУДЕТ СТРЕМИТЬСЯ ОСТАВИТЬ ДОВОЛЬНЫМ СВОЕГО ПРОРОКА МУХАММАДА (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ) ВО ВРЕМЯ ЗАСТУПНИЧЕСТВА В ДЕНЬ ВОСКРЕСЕНИЯ. ОНО БУДЕТ ПОВТОРЯТЬСЯ РАЗ ЗА РАЗОМ, ПОКА ПРОРОК (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ) НЕ СКАЖЕТ, ЧТО ОН ДОВОЛЕН ТЕМ ЗАСТУПНИЧЕСТВОМ ЗА ЧЛЕНОВ СВОЕЙ ОБЩИНЫ, КОТОРОЕ ЕМУ БЫЛО ДАНО"],["p","612 ― Харб ибн Сурейдж аль-Базза́р рассказывал: <i>«Однажды я сказал Абу Джа′фару Мухаммаду ибн ′Али ибн аль-Хусейну: \"Пусть я стану выкупом за тебя! Как ты считаешь, это заступничество, о котором говорят жители Ирака, является истиной?!\". Он спросил: \"Какое заступничество?\". Я сказал: \"Заступничество Мухаммада (да благословит его Аллах и приветствует)\". Он ответил: «Истина, клянусь Аллахом! Клянусь Аллахом, рассказал мне мой дядя Мухаммад, сын ′Али и аль-Ханафийи, со слов ′Али ибн Аби Талиба (да будет доволен им Аллах), что посланник Аллаха (да благословит его Аллах и приветствует) сказал: </i><b><i>«Я буду заступаться за свою общину, пока мой Господь не обратится ко мне и не скажет: \"Доволен ли ты, о Мухаммад?\", и я отвечу: \"Господь мой! Я доволен!\"». </i></b>"],["p","<i>После этого ′Али повернулся (к людям) и сказал: «О жители Ирака! Вы говорите, что больше всего надежды на благое даёт людям следующий аят в Книге Всевышнего Аллаха: </i><b>«Скажи Моим рабам, которые излишествовали во вред самим себе: \"Не отчаивайтесь в милости Аллаха. Воистину, Аллах прощает грехи полностью\"»</b><sup class=\"fn\">734</sup>. <i>Я ответил (ему): \"Да, мы говорим именно так!\". Тогда он сказал: «Но мы, члены семьи пророка (да благословит его Аллах и приветствует), говорим, что больше всего надежды на благое даёт людям следующий аят Книги Аллаха: </i><b>\"Господь твой непременно одарит тебя, и ты будешь удовлетворен\"</b><sup class=\"fn\">735</sup><i>»</i><sup class=\"fn\">736</sup>."],["n",[[734,"Сура «аз-Зумар», аят 53."],[735,"Сура «ад-Духа», аят 5."],[736,"Аль-Баззар, 638; ат-Табарани в «аль-Аусат», 2062; Абу Ну′айм в «Хильят аль-аулия», 3/179. Данная версия является очень слабой. А Аллах знает лучше!"]]],["p","ГЛАВА 64: РАЗЪЯСНЕНИЕ ТОГО, ЧТО ЕДИНОБОЖНИКИ, КОТОРЫМ ВСЕМОГУЩИЙ И ВЕЛИКИЙ АЛЛАХ ПРЕДОПРЕДЕЛИЛ ВЫХОД ИЗ ОГНЯ ПОСРЕДСТВОМ ЗАСТУПНИЧЕСТВА, СГОРЯТ ТАМ, ПОСЛЕ ЧЕГО АЛЛАХ УМЕРТВИТ ИХ. ТОЛЬКО ПОСЛЕ ЭТОГО БУДЕТ РАЗРЕШЕНО ЗАСТУПАТЬСЯ. А ТАКЖЕ РАЗЪЯСНЕНИЕ ОПИСАНИЯ ТОГО, КАК АЛЛАХ ОЖИВИТ ИХ ПОСЛЕ ТОГО, КАК ВЫВЕДЕТ ИЗ ИХ ОГНЯ, И ДО ТОГО, КАК ОНИ ВОЙДУТ В РАЙ"],["p","613 ― Абу Са′ид аль-Худри (да будет доволен им Аллах) передал, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Что касается обитателей Огня, которые останутся в нём навечно, то они не умрут там, но и жить не будут, однако некоторых людей Огонь коснётся за их грехи (или: за их прегрешения), и Аллах умертвит их. Когда же они превратятся в уголь, (за них) будет позволено обращаться с просьбами о заступничестве, после чего их станут приводить отдельными группами и рассеивать над райскими реками. А потом будет сказано: \"О обитатели Рая, лейте на них (воду)\", и они станут прорастать, как прорастает семя, оказавшееся в том, что приносит с собой поток».</i></b>"]],[["p","(Абу Са'ид сказал): <i>«(Услышав это), один человек из числа присутствующих сказал: \"Похоже, что посланник Аллаха (да благословит его Аллах и приветствует) сам (видел это) в пустыне\"»</i><sup class=\"fn\">737</sup>."],["n",[[737,"Ахмад, 3/11; Абу Я′ля, 1097, 1370; Ибн Джарир, 10/417, и др."]]],["p","614 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 613]."],["p","615 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 613]."],["p","616 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 613]."],["p","617 ― В другой версии со слов Абу Са′ида аль-Худри (да будет доволен им Аллах) пришло, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«(Некоторые) люди выйдут из Огня после того, как сгорят и превратятся в уголь. После этого на них прольют воду и они станут прорастать, как прорастает сор, принесённый потоком, а затем они войдут в Рай»</i></b><sup class=\"fn\">738</sup>."],["n",[[738,"Ахмад, 3/48; Ибн Манда в «аль-Иман», 836."]]],["p","618 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 617]."],["p","619 ― Анас ибн Малик (да будет доволен им Аллах) передал, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Из Огня выйдут некоторые люди после того, как превратятся в угли, а затем они войдут в Рай. Обитатели Рая скажут: \"Кто это?\", и им ответят: \"Джаханнамийюн\"»</i></b><sup class=\"fn\">739</sup>."],["n",[[739,"См. хадис № 591."]]],["p","ГЛАВА 65: РАЗЪЯСНЕНИЕ ТОГО, ЧТО ЛЮДИ, О КОТОРЫХ В ЭТИХ ХАДИСАХ ГОВОРИТСЯ, ЧТО ОНИ ВЫЙДУТ ИЗ ОГНЯ И ВОЙДУТ В РАЙ, ВЫЙДУТ ИЗ ОГНЯ ИМЕННО ПО ПРИЧИНЕ ЗАСТУПНИЧЕСТВА"],["p","620 ― Абу Са′ид аль-Худри (да будет доволен им Аллах) передал, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Что касается обитателей Огня, которые останутся в нём навечно, то они не умрут там, но и жить не будут, однако некоторых людей Огонь коснётся за их грехи (или: за их прегрешения), и Аллах умертвит их. Когда же они превратятся в уголь, (за них) будет позволено обращаться с просьбами о заступничестве, после чего их станут приводить отдельными группами и рассеивать над райскими реками. А потом будет сказано: \"О обитатели Рая, лейте на них воду\", и они станут прорастать, как прорастает семя, оказавшееся в том, что приносит с собой поток».</i></b>"],["p","(Абу Са'ид сказал): <i>«(Услышав это), один человек из числа присутствующих сказал: \"Похоже, что посланник Аллаха (да благословит его Аллах и приветствует) сам (видел это) в пустыне\"»</i><sup class=\"fn\">740</sup>."],["n",[[740,"См. хадис № 613. Автор (да помилует его Аллах) привёл этот хадис в данной главе из-за того, что в нём сказано: <b><i>«…будет позволено обращаться с просьбами о заступничестве, после чего их станут приводить отдельными группами…». </i></b>Значит, они выйдут из Огня именно по причине заступничества."]]]],[["p","621 ― В другой версии со слов Абу Са′ида аль-Худри (да будет доволен им Аллах) пришло, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Что касается обитателей Огня, которые останутся в нём навечно, то они не умрут там, но и жить не будут. Что же касается тех, кому Аллах пожелает милости (Своей), то их умертвит Огонь, после чего к ним придут заступники, и вот один человек возьмёт целую группу (людей) и бросит их в реку жизни (или: в реку Рая), и они станут прорастать, как прорастает семя, оказавшееся в том, что приносит с собой поток». </i></b>"],["p","Затем пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Разве вы не видите, что дерево бывает зелёным, а затем становится жёлтым, а затем вновь становится зелёным». </i></b>"],["p","Услышав это, один человек из числа присутствующих сказал:<i> \"Посланник Аллаха (да благословит его Аллах и приветствует) будто был из числа бедуинов\"</i><sup class=\"fn\">741</sup><i>»</i><sup class=\"fn\">742</sup>."],["n",[[741,"Потому что пророк (да благословит его Аллах и приветствует) описал, как это происходит во время селевых потоков в пустынях."],[742,"Ахмад, 3/5; Ибн Манда в «аль-Иман», 826."]]],["p","622 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 621]."],["p","623 ― В другой версии со слов Абу Са′ида аль-Худри (да будет доволен им Аллах) пришло, что посланник Аллаха (да благословит его Аллах и приветствует) однажды обращался к людям с проповедью и прочитал следующие аяты: <b>«Тому, кто явится к своему Господу, будучи грешником, уготована Геенна, в которой он не умрет и не будет жить. А тем, кто явится к Нему, будучи верующим, совершив праведные деяния, уготованы высшие ступени»</b><sup class=\"fn\">743</sup>."],["n",[[743,"Сура «Та Ха», аяты 74-75."]]],["p","Затем пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Что касается обитателей Огня, которые останутся в нём навечно, то они не умрут там, но и жить не будут. Что же касается тех людей, которые не относятся к вечным обитателям Огня, то Огонь умертвит их, после чего придут заступники и начнут заступаться. Их будут приводить группами к реке, которую именуют рекой жизни, и они станут прорастать в ней, как прорастает сор, принесённый потоком»</i></b><sup class=\"fn\">744</sup>."],["n",[[744,"Ибн Манда в «аль-Иман», 825."]]],["p","ГЛАВА 66: УПОМИНАНИЕ ДОВОДА, УКАЗЫВАЮЩЕГО НА ТО, ЧТО КОГДА ПРОРОК (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ) СКАЗАЛ, ЧТО ОНИ ПРЕВРАТЯТСЯ В УГОЛЬ, ОН ИМЕЛ В ВИДУ ИХ ТЕЛА, ЗА ИСКЛЮЧЕНИЕМ ИХ ЛИЦ И СЛЕДОВ ОТ ЗЕМНЫХ ПОКЛОНОВ"],["p","Всемогущий и Великий Аллах запретил Огню пожирать следы от земных поклонов на тех людях, которые исповедовали единобожие. Мы просим у Аллаха защиты от Огня и его наказания!"],["p","624 ― Абу Хурейра (да будет доволен им Аллах) передал, что однажды некоторые люди сказали: <i>«О посланник Аллаха! Увидим ли мы нашего Господа в День Воскресения?». </i>Затем приходит длинный хадис, в котором пророк (да благословит его Аллах и приветствует) среди прочего сказал: <b><i>«Затем (Аллах) пожелает проявить милость к некоторым обитателям Огня и прикажет ангелам вывести тех, кто поклонялся Аллаху. (Ангелы) будут выводить их, узнавая их по следам от земных поклонов, ведь Аллах запретил Огню пожирать следы от земных поклонов. Потом их выведут из Огня обгоревшими и польют водой жизни, благодаря чему они станут расти так же, как прорастает семя из того, что приносит с собой поток. А потом, когда Аллах завершит Суд над Своими рабами, останется один человек между Раем и Адом, и он будет последним, кто войдёт в Рай из его обитателей», </i></b>и так далее до конца хадиса<sup class=\"fn\">745</sup>."],["n",[[745,"Аль-Бухари, 6573, 6574; Муслим, 182."]]]],[["p","625 ― [Под этим номером приведено то же самое сообщение, что и под № 624]."],["p","626 ― [Под этим номером приведено то же самое сообщение, что и под № 624]."],["p","627 ― Абу Са′ид аль-Худри (да будет доволен им Аллах) передал, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Когда верующие избавятся от Огня и обретут безопасность, они будут сильнее просить своего Господа за своих братьев, которые были введены в Огонь, чем один из вас спорил в ближней жизни с тем, кто должен был ему что-то</i></b><sup class=\"fn\">746</sup><b><i>. Они скажут: \"Господь наш! Наши братья совершали молитву вместе с нами, соблюдали пост вместе с нами, совершали хадж вместе с нами. Неужели Ты ввёл их в Огонь?!\". Он скажет: \"Ступайте и выведите тех, кого вы знали\", и тогда они придут к ним и узнают их по их лицам. Огонь не поглотит их лица!», </i></b>и так далее до конца хадиса<sup class=\"fn\">747</sup>."],["n",[[746,"Иначе говоря, споры людей друг с другом в ближней жизни по поводу каких-то долгов и обязательств – это ничто по сравнению с тем, как верующие будут просить своего Всевышнего Господа в Последней жизни, когда им будут разрешено войти в Рай, а их братьев введут в Ад из-за их грехов. Они начнут молить Всевышнего Аллаха, чтобы он вывел их братьев из Огня и чтобы те вошли в Рай вместе с ними."],[747,"′Абд ур-Раззак в «Мусаннафе», 20857; Ахмад, 3/94; Муслим, 183; Ибн Манда в «аль-Иман», 818."]]],["p","628 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 627]."],["p","629 ― И пришло в хадисе со слов ′Итбана ибн Малика (да будет доволен им Аллах), что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Поистине, Аллах запретил Огонь для того, кто сказал: \"Ля иляха илля Ллах\", стремясь этим к лику Аллаха»</i></b><sup class=\"fn\">748</sup>."],["n",[[748,"Хадис придёт под № 724, если пожелает Аллах."]]],["p","ГЛАВА 67: РАЗЪЯСНЕНИЕ ПО ПОВОДУ ТЕХ ЛЮДЕЙ, КОМУ АЛЛАХ ПРЕДОПРЕДЕЛИЛ ВЫХОД ИЗ ОГНЯ, ИЗ ЧИСЛА ПРИВЕРЖЕНЦЕВ ЕДИНОБОЖИЯ, КОТОРЫЕ НЕ ЯВЛЯЮТСЯ ВЕЧНЫМИ ОБИТАТЕЛЯМИ ОГНЯ. ОГОНЬ УМЕРТВИТ ИХ, А ЗАТЕМ ОНИ ВЫЙДУТ ИЗ НЕГО И ВОЙДУТ В РАЙ. ТО ЕСТЬ ОНИ НЕ БУДУТ ЖИВЫМИ ВКУШАТЬ НАКАЗАНИЕ И ИСПЫТЫВАТЬ БОЛЬ ОТ АДСКОГО ЖАРА, ПОКА НЕ ВЫЙДУТ ИЗ НЕГО"],["p","630 ― Пришло в хадисе со слов Абу Са′ида (да будет доволен им Аллах), что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«…однако некоторых людей Огонь коснётся за их грехи (или: за их прегрешения), и (Аллах) умертвит их. После этого их бросят в райские реки и скажут обитателям Рая: \"Лейте на них (воду)\"»</i></b><sup class=\"fn\">749</sup>."],["n",[[749,"Полная версия этого хадиса была приведена под № 613."]]],["p","631 ― [Под этим номером приведено то же самое сообщение, что и под № 630]."],["p","632 ― В другой версии слов Абу Са′ида (да будет доволен им Аллах) пришло: <b><i>«А когда они превратятся в уголь, за них будет разрешено заступиться».</i></b>"]],[["p","По этому поводу Всемогущий и Великий Аллах сказал: <b>«Ничье заступничество перед Ним не принесет пользы, кроме тех, кому будет дозволено»</b><sup class=\"fn\">750</sup>. То есть кроме тех, за кого Аллах разрешит заступаться из числа тех, кто умрёт в Аду, не являясь его вечным обитателем."],["n",[[750,"Сура «Саба», аят 23."]]],["p","633 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 630]."],["p","634 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 630]."],["p","635 ― В другой версии слов Абу Са′ида аль-Худри (да будет доволен им Аллах) пришло, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Что касается обитателей Огня, которые останутся в нём навечно, то они не умрут там, но и жить не будут. Что же касается тех, кого Аллах пожелает вывести из Огня, то Огонь умертвит таких, и они превратятся в уголь. Затем они начнут выходить группами, и их будут бросать в райские реки, и проливать на них воду из этих рек, и они станут прорастать, как прорастает семя, оказавшееся в том, что приносит с собой поток. Они войдут в Рай, а обитатели Рая будут называть их \"джаханнамийюн\". Тогда они обратятся с мольбой к Аллаху, и Он удалит от них это прозвище»</i></b><sup class=\"fn\">751</sup>."],["n",[[751,"Ибн Манда в «аль-Иман», 834."]]],["p","636 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 635, но только со слов самого Абу Са′ида (да будет доволен им Аллах), а не со слов пророка (да благословит его Аллах и приветствует)]."],["p","637 ― Аль-Мугыра ибн Шу′ба (да будет доволен им Аллах) передал, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«(Некоторые) люди выйдут из Огня и войдут в Рай, и в Раю их будут называть \"джаханнамийюн\". Тогда они станут просить Аллаха, чтобы Он удалил от них это прозвище, и Он сделает это»</i></b><sup class=\"fn\">752</sup><b><i>.</i></b>"],["n",[[752,"Данный хадис является очень слабым. А Аллах знает лучше!"]]],["p","ГЛАВА 68: УПОМИНАНИЕ ХАДИСА ПРОРОКА (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ), В КОТОРОМ ГОВОРИТСЯ О ТОМ, ЧТО ЧЕЛОВЕК, КОТОРЫЙ ЗАСВИДЕТЕЛЬСТВОВАЛ, ЧТО НЕТ ИСТИННОГО БОГА, КРОМЕ АЛЛАХА, БУДЕТ ВЫВЕДЕН ИЗ ОГНЯ"],["p","Я боюсь, что этот хадис услышат какие-нибудь невежды и подумают, что он касается того, кто просто произнёс эти слова языком, не уверовав в них сердцем; подумают, что такой выйдет из Огня. Такое понимание возможно по причине невежества и малых знаний о религии Аллаха и Его постановлениях, и по причине незнания хадисов пророка (да благословит его Аллах и приветствует). Мы очень сильно боимся того, что некоторые невежды подумают, что человек, который засвидетельствовал «ля иляха илля Ллах», но при этом не засвидетельствовал, что у Аллаха есть посланники и Книги, Рай и Ад, воскрешение и расчёт, войдет в Рай. Ведь большинство людей в наше время не понимают эту науку и не различают между полными версиями хадисов и сокращёнными версиями. Возможно, до них не дошла полная версия хадиса, и они будут аргументировать его сокращённой версией. Такие люди пытаются встать во главе до того, как обучились. Они были лишены терпеливого поиска знаний и не проявили терпение, чтобы заслужить главенство и достичь степеней учёных."]],[["p","638 ― Анас ибн Малик (да будет доволен им Аллах) передал, что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Я буду обращаться с мольбами о заступничестве к своему Господу, а он будет принимать моё заступничество, а, в конце концов, я скажу: «О Господь мой! Прими моё заступничество относительно тех, кто сказал: \"Ля иляха илля Ллах\"». Он скажет: «О Мухаммад! Это не касается ни тебя, ни кого-то другого. Клянусь Своим величием и могуществом, Я не оставлю в Аду никого, кто сказал: \"Ля иляха илля Ллах\"». </i></b>"],["p","В другой версии пришло: <b><i>«Поистине, это сделаю Я. Клянусь Своим величием, могуществом и милостью! Я не оставлю в Аду раба, который сказал: \"Ля иляха илля Ллах\"».</i></b>"],["p","В третьей версии пришло: <b><i>«Это сделаю Я. В Аду не останется никого, кто сказал: \"Ля иляха илля Ллах\", кроме как Я обязательно выведу его»</i></b><sup class=\"fn\">753</sup>."],["n",[[753,"Абу Я′ля, 2786; Ибн Аби ′Асым в «ас-Сунна», 728."]]],["p","639 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 638]<sup class=\"fn\">754</sup>."],["n",[[754,"Полная версия этого хадиса придёт под № 661, если пожелает Аллах."]]],["p","640 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 638]."],["p","ГЛАВА 69: РАЗЪЯСНЕНИЕ ТОГО, ЧТО ПРОРОК (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ) БУДЕТ ЗАСТУПАТЬСЯ ЗА ТОГО, КТО СВИДЕТЕЛЬСТВОВАЛ СВОИМ ЯЗЫКОМ О ЕДИНОБОЖИИ АЛЛАХА И БЫЛ ЕДИНОБОЖНИКОМ, ЕСЛИ ОН ПРИ ЭТОМ БЫЛ ИСКРЕННИМ И ПОДТВЕРЖДАЛ ЭТИ СЛОВА СВОИМ СЕРДЦЕМ. И ОН НЕ БУДЕТ ЗАСТУПАТЬСЯ ЗА ТОГО, ЧЬЁ СВИДЕТЕЛЬСТВО НЕ ПОДТВЕРЖДАЛОСЬ ЕГО СЕРДЦЕМ"],["p","641 ― Абу Хурейра (да будет доволен им Аллах) рассказывал: <i>«Однажды я спросил посланника Аллаха (да благословит его Аллах и приветствует): \"О посланник Аллаха! Что даровал тебе твой Господь из заступничества?\". Он ответил: </i><b><i>\"Клянусь Тем, в Чьей руке душа Мухаммада! Я так и думал, что ты будешь первым, кто спросит меня об этом из (членов) моей общины, ибо видел твоё стремление к знанию. Клянусь Тем, в Чьей руке моя душа! Мои мысли о том, как они будут толпиться у врат Рая, важнее для меня, чем моё заступничество, однако моё заступничество достанется каждому, кто засвидетельствовал, что нет истинного бога, кроме Аллаха, будучи искренним, и при этом его сердце подтвердило то, что у него на языке, а язык подтвердил то, что у него в сердце\"</i></b><i>»</i><sup class=\"fn\">755</sup>."],["n",[[755,"Ахмад, 2/307; аль-Хаким в «аль-Мустадрак», 233 и др."]]],["p","642 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 641]."],["p","643 ― [Под этим номером приведено то же самое сообщение, что и под № 641]."],["p","644 ― Абу Хурейра (да будет доволен им Аллах) также рассказывал: <i>«Однажды я спросил: \"О посланник Аллаха! Кто станет самым счастливым из людей посредством твоего заступничества в День Воскресения?\". Пророк (да благословит его Аллах и приветствует) ответил: </i><b><i>«Я так и думал, о Абу Хурейра, что никто не спросит меня об этом раньше тебя, ибо видел твоё стремление к хадисам. Самым счастливым из людей посредством моего заступничества в День Воскресения будет тот, кто сказал: \"Ля иляха илля Ллах\" (нет истинного бога, кроме Аллаха), будучи искренним в своей душе»</i></b><sup class=\"fn\">756</sup>."],["n",[[756,"Аль-Бухари, 6570, и др."]]]],[["p","ГЛАВА 70: УПОМИНАНИЕ ХАДИСА, УКАЗЫВАЮЩЕГО НА ДОСТОВЕРНОСТЬ МОЕГО ПОНИМАНИЯ, ГЛАСЯЩЕГО, ЧТО ВЫЙДУТ ИЗ ОГНЯ ТОЛЬКО ТЕ, КТО ЗАСВИДЕТЕЛЬСТВОВАЛ, ЧТО НЕТ ИСТИННОГО БОГА, КРОМЕ АЛЛАХА, И ПРИ ЭТОМ ПОДТВЕРЖДАЛ СВОИМИ СЕРДЦАМИ ТО, ЧТО ЗАСВИДЕТЕЛЬСТВОВАЛИ ИХ ЯЗЫКИ."],["p","Однако в этом хадисе пророк (да благословит его Аллах и приветствует) использовал слово «хайр» (благо), говоря о подтверждении сердцем. Некоторые люди невежества и упрямства стали упрямиться и заявлять, что слово «хайр» (благо) в этом хадисе не указывает на веру (иман). Скудные знания о религии Аллаха и дерзость против Аллаха побудили их назвать лицемеров верующими."],["p","645 ― Анас ибн Малик (да будет доволен им Аллах) передал, что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Аллах скажет: «Выведите из Огня тех, кто сказал: \"Ля иляха илля Ллах\", и при этом в их сердце было благо весом с ячменное зерно. Выведите из Огня тех, кто сказал: \"Ля иляха илля Ллах\", и при этом в их сердце было благо весом с пшеничное зерно. Выведите из Огня тех, кто сказал: \"Ля иляха илля Ллах\", и при этом в их сердце было благо весом с насекомое. Выведите из Огня тех, кто сказал: \"Ля иляха илля Ллах\", и при этом в их сердце было благо весом с букашку»</i></b><sup class=\"fn\">757</sup>."],["n",[[757,"Ахмад, 3/276; ′Абд ибн Хумейд, 1172; Ибн Манда в «аль-Иман», 872. Также похожий хадис передал Муслим, 193."]]],["p","646 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 645]."],["p","647 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 645]<sup class=\"fn\">758</sup>."],["n",[[758,"Эту версию привели ат-Тирмизи, 2593; ат-Таялиси, 1966, и др. Мы не стали приводить её целиком, ибо она практически не отличается от версии, приведённой в начале главы."]]],["p","648 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 645]<sup class=\"fn\">759</sup>."],["n",[[759,"Эту версию привели аль-Бухари, 7410; Муслим, 193, и др. Мы не стали приводить её целиком, ибо она практически не отличается от версии, приведённой в начале главы."]]],["p","649 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 645]."],["p","650 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 645]<sup class=\"fn\">760</sup>."],["n",[[760,"Эту версию привели Муслим, 193; Ахмад, 3/116, и др. Мы не стали приводить её целиком, ибо она практически не отличается от версии, приведённой в начале главы."]]],["p","651 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 645]<sup class=\"fn\">761</sup>."],["n",[[761,"Таким образом, автор (да помилует его Аллах) упомянул много разных версий одного и того же хадиса, чтобы ещё сильнее подтвердить то, о чём он говорит."]]],["p","ГЛАВА 71: УПОМИНАНИЕ ХАДИСОВ, В КОТОРЫХ ПРОРОК (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ) ЯСНО ГОВОРИТ, ЧТО ВЫЙДЕТ ИЗ ОГНЯ ТОЛЬКО ТОТ, У КОГО В СЕРДЦЕ В БЛИЖНЕЙ ЖИЗНИ БЫЛА ВЕРА. И НЕ ВЫЙДЕТ ИЗ ОГНЯ ТОТ, У КОГО В СЕРДЦЕ В БЛИЖНЕЙ ЖИЗНИ НЕ БЫЛО ВЕРЫ, А ОН ПРОСТО ПОДТВЕРЖДАЛ ЕДИНОБОЖИЕ СВОИМ ЯЗЫКОМ, КОГДА ВЕРА В ЕГО СЕРДЦЕ ОТСУТСТВОВАЛА"]],[["p","При этом нужно разъяснить, что люди разнятся в той вере, которая у них в сердце, а не так, как говорят крайние мурджииты, что вера (иман) вообще не бывает в сердце, и не так, как говорят другие (не мурджииты), что люди отличаются друг от друга только в вере своих органов, то есть в том, что они совершают своими телами. Они посчитали, что все люди одинаковы в той вере, которая у них в сердце, и в вере языка, которая представляет из себя признание истины языком. Также необходимо разъяснить, что пророку (да благословит его Аллах и приветствует) будут даны разные виды заступничества в День Воскресения, как я уже разъяснял ранее, а не только один вид заступничества."],["p","652 ― Абу Са′ид аль-Худри (да будет доволен им Аллах) передал, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«(Аллах) введёт в Рай обитателей Рая, и Он введёт туда тех, кого пожелает, по Своей милости, и Он введёт обитателей Ада в Ад, а затем скажет: \"Посмотрите, и если вы найдёте в чьём-либо сердце веру весом с горчичное зерно, то выведите его!\", и тогда (эти люди) выйдут оттуда сгоревшими, и их бросят в реку жизни (или</i></b><sup class=\"fn\">762</sup><b><i>: в ту реку, которая образовалась после дождя), и они вырастут, как вырастает семя, оказавшееся на берегу потока. Разве вы не видели, как оно выходит жёлтым и согнутым?!»</i></b><sup class=\"fn\">763</sup>."],["n",[[762,"Сомнение со стороны передатчика хадиса."],[763,"Аль-Бухари, 22, 6560; Муслим, 184; Ахмад, 3/56, и др."]]],["p","Здесь этот хадис приведён в сокращённом виде. Здесь не упомянуто начало истории, где говорится о заступничестве за того, кто был введён в Огонь из единобожников. Здесь упомянут только конец истории. Я приведу довод, который указывает на то, что данный хадис приведён в сокращённом виде."],["p","653 ― В другой версии со слов Абу Са′ида аль-Худри (да будет доволен им Аллах) пришло, что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«И Аллах скажет: \"Посмотрите, и если в чьём-либо сердце есть вера весом с динар, то выведите его\"». </i></b>И затем он также упомянул вес кыра́та, а затем также упомянул вес горчичного зерна."],["p","Я привёл этот хадис в полном виде во многих главах."],["p","654 ― Также Абу ′Усман ан-Нахди передал, что Сальман аль-Фариси (да будет доволен им Аллах) рассказывал: <i>«Люди придут к пророку (да благословит его Аллах и приветствует) и скажут: \"О пророк Аллаха! Посредством тебя Аллах даровал победу и посредством тебя Аллах завершил, и Он простил тебе все прошлые и будущие грехи. Вставай же и заступись за нас пред своим Господом\". Он ответит: \"Да, именно я сделаю это для вас!\". Тогда он отправится на поиски Огня и так дойдёт до райских врат, схватится за золотое кольцо на вратах, и постучит в дверь, и тогда ему скажут: \"Кто это?\". Он ответит: \"Мухаммад\", и ему откроют. Он пойдёт (дальше) и встанет пред Аллахом, и попросит разрешения совершить земной поклон, и ему разрешат. И тогда Аллах откроет ему такие виды славословия, восхваления и прославления, какие не открывал никому из творений. Затем раздастся глас: \"О Мухаммад! Подними свою голову! Проси, и тебе будет даровано, взывай, и тебе будет отвечено!\". Он поднимет голову и скажет: \"Господь мой! Моя община! Моя община!\". Затем он вновь попросит разрешения совершить земной поклон, и ему разрешат, и Аллах откроет ему такие виды славословия, восхваления и прославления, какие не открывал никому из творений. Затем раздастся глас: \"О Мухаммад! Подними свою голову! Проси, и тебе будет даровано, заступайся, и твоё заступничество будет принято, взывай, и тебе будет отвечено!\". Это случится два или три раза, и он заступится за тех, у кого в сердце была вера весом с пшеничное зерно или с ячменное зерно, или с горчичное зерно. Это и есть достохвальное место (мака́м махму́д)»</i><sup class=\"fn\">764</sup>."],["n",[[764,"Ибн Аби Шейба в «Мусаннафе», 31675; Ибн Аби ′Асым в «ас-Сунна», 813; ат-Табарани в «аль-Кабир», 6/247. Учёные говорят, что хоть это сообщение и является словами сподвижника, но его слова подобны словам самого пророка (да благословит его Аллах и приветствует), ибо сподвижник не мог высказываться о таком на основе своего мнения. Он передавал именно то, что слышал от пророка (да благословит его Аллах и приветствует). А Аллах знает лучше!"]]]],[["p","Это сообщение является более полным в истории о выведении людей из Огня, чем хадис со слов Абу Са′ида аль-Худри (да будет доволен им Аллах), который от него передавал Яхья ибн ′Умара. В этом сообщение упомянут вес пшеничного зерна и вес ячменного зерна, а в хадисе со слов Абу Са′ида (да будет доволен им Аллах), который от него передавал Яхья ибн ′Умара, этого нет. В хадисе со слов Анаса (да будет доволен им Аллах), который от него передавал ′Убейдуллах ибн Аби Бакр, также упоминается ячменное зерно и пшеничное зерно. Также в нём упоминается вес букашки, но не упоминается вес горчичного зерна. Все эти хадисы указывают на правильность нашего мнения, когда мы говорим, что хадисы передаются так, как их запомнили их передатчики. Кто-то из них запомнил только часть хадиса, а кто-то запомнил весь хадис. Поэтому некоторые хадисы переданы в сокращённом виде, а некоторые – в полном. И если человек соберёт полные версии вместе с сокращёнными версиями, для него тогда прояснится знание и религиозное постановление."],["p","655 ― Анас ибн Малик (да будет доволен им Аллах) передал, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Всемогущий и Великий Аллах скажет: «Выведите из Огня тех, в чьём сердце есть вера весом с ячменное зерно. Выведите из Огня тех, в чьём сердце есть вера весом с пшеничное зерно. Выведите из Огня тех, кто сказал: \"Ля иляха илля Ллах\" или поминал Меня, или испытал страх передо Мной»</i></b><sup class=\"fn\">765</sup>."],["n",[[765,"Данная версия является слабой. А Аллах знает лучше!"]]],["p","656 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 655]<sup class=\"fn\">766</sup>."],["n",[[766,"Эта версия также является слабой. А Аллах знает лучше!"]]],["p","657 ― В другой версии со слов Анаса ибн Малика (да будет доволен им Аллах) пришло, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Аллах скажет: \"Выведите из Огня тех, кто вспомнил обо Мне в один из дней или испытал страх передо Мной в какой-нибудь ситуации!\"»</i></b><sup class=\"fn\">767</sup>."],["n",[[767,"Эту версию также привели ат-Тирмизи, 2594; Ибн Аби ′Асым в «ас-Сунна», 833, и др, но и она является недостоверной. А Аллах знает лучше!"]]],["p","658 ― ′Амр ибн Аби ′Амр передал со слов Анаса ибн Малика (да будет доволен им Аллах), что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Поистине, я буду первым человеком, над головой которого раскроется земля в День Воскресения, но я не бахвалюсь этим. И мне будет даровано знамя хвалы, но я не бахвалюсь этим. И я – господин пророков в День Воскресения, но я не бахвалюсь этим. И я буду первым, кто войдёт в Рай в День Воскресения, но я не бахвалюсь этим. Я подойду к райским вратам, и мне откроют, и тогда я паду ниц перед Всевышним Аллахом, и Он скажет: \"Подними голову, о Мухаммад! Говори, и твои слова будут услышаны, говори, и от тебя будет принято, заступайся, и твоё заступничество будет удовлетворено\", и я подниму голову и скажу: \"Моя община! Моя община! О Господь мой!\". Он скажет: \"Ступай к своей общине и введи в Рай тех, в чьём сердце ты найдёшь веру весом с ячменное зерно!\". Я подойду к тем, в чьём сердце я найду такую (веру), и введу их в Рай. Затем я подойду к Могущественному, паду пред Ним ниц, и Он скажет: \"Подними голову, о Мухаммад! Говори, и твои слова будут услышаны, говори, и от тебя будет принято, заступайся, и твоё заступничество будет удовлетворено\", и я подниму голову и скажу: \"Моя община! Моя община! О Господь мой!\". Он скажет: \"Ступай к своей общине и введи в Рай тех, в чьём сердце ты найдёшь веру весом с половину ячменного зерна!\". Я отправлюсь к ним и введу в Рай тех, в чьём сердце я найду (веру) такого веса. Затем я подойду к Могущественному, паду пред Ним ниц, и Он скажет: \"Подними голову, о Мухаммад! Говори, и твои слова будут услышаны, заступайся, и твоё заступничество будет удовлетворено\", и я подниму голову и скажу: \"Моя община! Моя община! О Господь мой!\". Он скажет: \"Ступай к своей общине и введи в Рай тех, в чьём сердце ты найдёшь веру весом с горчичное зерно!\". Я отправлюсь к ним и введу в Рай тех, в чьём сердце я найду (веру) такого веса. После этого закончится расчёт людей»</i></b><sup class=\"fn\">768</sup>."],["n",[[768,"Данная версия уже является достоверной. Её также передали Ахмад, 3/144; ад-Дарими, 52; Ибн Манда в «аль-Иман», 877, и др."]]]],[["p","659 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 658, но в нём есть дополнение, которое мы приведём ниже]."],["p","[В этой версии пришло, что пророк (да благословит его Аллах и приветствует) сказал после тех слов, что были приведены выше]: <b><i>«А те (члены) моей общины, которые остались в Аду, окажутся вместе с обитателями Ада (из числа неверующих), и эти обитатели Ада скажут им: \"Вам ничем не помогло то, что вы поклонялись Ему и ничего не придавали Ему в сотоварищи! Вот вы с нами!\". Тогда Могущественный (Аллах), Всеблагой и Всевышний, скажет: \"Клянусь Своим величием! Я непременно освобожу их из Огня!\". Затем Он отправит за ними, и они выйдут из Огня, но будут сгоревшими. Затем они войдут в райскую реку и вырастут в ней, как произрастает семя, которое принёс с собой поток воды, а меж их глаз будет записано: \"Это – те, кого освободил Аллах!\". После этого их приведут к Раю, и они войдут в него, и обитатели Рая скажут: \"Это - джаханнамийюн</i></b><sup class=\"fn\">769</sup><b><i>\", а Могущественный (Аллах) скажет: \"Это – те, кого освободил Могущественный!\"».</i></b>"],["n",[[769,"От слова «джаханнам» (адское пламя, геенна)."]]],["p","660 ― В другой версии со слов Анаса (да будет доволен им Аллах) пришло, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Выйдут из Огня те, в чьём сердце была вера (иман) весом с горчичное зерно или весом с пшеничное зерно, или весом с букашку»</i></b><sup class=\"fn\">770</sup>."],["n",[[770,"Это сокращённая версия того хадиса, который был приведён в предыдущей главе."]]],["p","Вера (иман) – это благо, а не зло, как мы знаем. А те крайние мурджииты, которые считают, что упоминание слова «хайр» (благо) в этих хадисах не указывает на «иман» (вера), называют ложью все эти хадисы, в которых сказано: <b><i>«Выведите из Огня тех, в чьём сердце была такая-то и такая-то вера». </i></b>Они должны сказать, что все эти хадисы не являются достоверными. Или же они должны сказать, что под словом «иман» имеется в виду какой-то другой «иман». Или же они должны сказать, что «иман» (вера) не является благом, а то, что не является благом, является злом. И мусульманин никогда не скажет, что «иман» (вера) не является благом. Пойми же этот вопрос и не впадай в заблуждение!"],["p","661 ― Ма′бад ибн Хиляль аль-′Анази рассказывал: <i>«Однажды мы отправились к Анасу ибн Малику вместе с Сабитом аль-Бунани из-за этого хадиса. Сабит попросил разрешения войти, и он разрешил нас, и мы вошли к нему. Он посадил Сабита рядом с собой на ложе, и я сказал своим спутникам: \"Не спрашивайте его ни о чём, кроме этого хадиса! Ведь мы вышли (в путь) только ради него\". Сабит сказал: \"О Абу Хамза! Твои братья из Басры пришли к тебе, чтобы спросить тебя о хадисе посланника Аллаха (да благословит его Аллах и приветствует), в котором говорится о заступничестве\". Он сказал: «Да. Мухаммад, посланник Аллаха, (да благословит его Аллах и приветствует) рассказал мне: </i>"]],[["p","<b><i>«Когда наступит День Воскресения, люди будут бросаться друг к другу, а затем придут к Адаму и скажут: \"О Адам! Заступись за своих потомков!\". Он ответит: \"Я не подхожу для этого, но вам следует отправиться к Ибрахиму, ведь, поистине, он – любимец Аллаха\". Когда они придут к Ибрахиму, он ответит: \"Я не подхожу для этого, но вам следует отправиться к Мусе, ведь, поистине, он – тот, с кем говорил Аллах\". Когда они придут к Мусе, он ответит: \"Я не подхожу для этого, но вам следует отправиться к ′Исе, ведь, поистине, он – дух от Аллаха и слово от Него\". Когда они придут к ′Исе, он ответит: \"Я не подхожу для этого, но вам следует отправиться к Мухаммаду (да благословит его Аллах и приветствует)\", и они придут ко мне. </i></b>"],["p","<b><i>Тогда я скажу: \"Я – для этого\", и отправлюсь, чтобы попросить разрешения обратиться к моему Господу, и мне будет разрешено это, и я тогда я встану пред Ним, и Он внушит мне такие слова восхваления, которые я не могу произнести сейчас. Я стану восхвалять Его этими словами, а затем паду ниц, после чего мне скажут: \"О Мухаммад! Подними голову! Говори, и тебя услышат, проси, и тебе будет даровано, заступайся, и твоё заступничество будет принято!\". Я скажу: \"О Господь мой! Моя община! Моя община!\". И тогда мне скажут: \"Ступай, и если в чьём-либо сердце будет вера весом с пшеничное зерно (или же он сказал: ячменное зерно), то выведи его из Огня!\". Я отправлюсь (туда) и сделаю это. </i></b>"],["p","<b><i>Потом я вернусь и (снова) воздам Ему эту хвалу, после чего склонюсь перед Ним в земном поклоне, и (мне) будет сказано: \"О Мухаммад! Подними голову! Говори, и тебя услышат, проси, и тебе будет даровано, заступайся, и твоё заступничество будет принято!\". Я скажу: \"О Господь мой! Моя община! Моя община!\". И тогда мне скажут: \"Ступай, и если в чьём-либо сердце будет вера весом с самое-самое-самое маленькое горчичное зерно, то выведи его из Огня!\". Я отправлюсь (туда) и сделаю это». </i></b>"],["p","Ма′бад также рассказывал: <i>«Мы покинули его, и когда мы шли по пустыне, я сказал: \"О, если бы мы отправились к аль-Хасану (аль-Басри)\", а он скрывался в доме Абу Халифы</i><sup class=\"fn\">771</sup><i>. И вот мы пришли к нему, и сказали: \"О Абу Са′ид! Мы пришли от твоего брата Абу Хамзы\", и мы рассказали ему хадис, (услышанный нами), а когда мы закончили он сказал: \"Он рассказал вам только это?\". Мы сказали: \"Он ничего более не рассказывал\". Тогда аль-Хасан сказал: \"Он рассказывал мне этот хадис двадцать лет назад, и я не знаю, забыл ли шейх или не захотел рассказывать вам его (полностью), чтобы вы не стали полагаться (на этот хадис и не оставили совершение дел)\". (Люди) сказали: \"О Абу Са′ид! Расскажи же нам!\". Он засмеялся и сказал: «Человек сотворён торопливым! Он рассказал мне этот хадис так же, как рассказал вам, двадцать лет назад, а затем добавил следующее: </i>"],["n",[[771,"Он скрывался от тирана аль-Хаджжаджа ибн Юсуфа."]]]],[["p","<b><i>«И я встану в четвёртый раз, и (снова) воздам Ему эту хвалу, после чего склонюсь перед Ним в земном поклоне, и (мне) будет сказано: \"Подними голову! Говори, и тебя услышат, проси, и тебе будет даровано, заступайся, и твоё заступничество будет принято!\". Я подниму голову и скажу: «О Господь мой! Позволь мне обратиться к Тебе с заступничеством за тех, кто говорил: \"Ля иляха илля Ллах\"». Он скажет: «Нет, это не для тебя, но клянусь Своей славой, величавостью и величием, Я обязательно выведу оттуда тех, кто говорил: \"Ля иляха илля Ллах\"»</i></b><sup class=\"fn\">772</sup>."],["n",[[772,"Аль-Бухари, 7510; Муслим, 193; ан-Насаи в «ас-Сунан аль-кубра», 11131, и др."]]],["p","662 ― Хумейд ат-Тавиль передал, что Анас ибн Малик (да будет доволен им Аллах) рассказывал, (передавая слова пророка, да благословит его Аллах и приветствует): <b><i>«В День Воскресения люди будут задержаны столько, сколько пожелает Аллах, после чего они скажут: \"Пойдемте к Адаму\". Они отправятся к Адаму и скажут: \"О Адам! Заступись за нас пред твоим Господом!\", но он ответит: \"Я не для этого, однако идите к любимцу Аллаха Ибрахиму\". Они отправятся к Ибрахиму и скажут: \"О Ибрахим! Заступись за нас пред твоим Господом!\", но он ответит: \"Я не для этого, однако ступайте к тому, кого Аллах избрал Своим посланием\". Они отправятся к Мусе и скажут: \"О Муса! Заступись за нас пред твоим Господом!\", но он ответит: \"Я не для этого, однако ступайте к тому, кто пришёл сегодня прощённым, без единого греха\". Тогда они отправятся к Мухаммаду и скажут: \"О Мухаммад! Заступись за нас пред твоим Господом!\". Он скажет: \"Я для этого. Я буду заступаться!\". И тогда я отправлюсь к вратам Рая, и попрошу отворить их, а затем войду. Мой Всемогущий и Великий Господь будет над Своим троном, и я паду ниц, и восхвалю Его восхвалениями, которыми не восхвалял Его никто прежде меня и не восхвалит никто после меня. После этого будет сказано: \"О Мухаммад! Подними голову! Говори, и тебя услышат, проси, и тебе будет даровано, заступайся, и твоё заступничество будет принято!\". Я скажу: \"О Господь мой! О Господь мой!\". (Аллах) скажет: \"Выведи (из Огня) тех, в чьём сердце была вера весом с ячменное зерно!\". Затем я вновь паду ниц и восхвалю Его восхвалениями, которыми не восхвалял Его никто прежде меня и не восхвалит никто после меня. После этого будет сказано: \"О Мухаммад! Подними голову! Говори, и тебя услышат, проси, и тебе будет даровано, заступайся, и твоё заступничество будет принято!\". Я скажу: \"О Господь мой! О Господь мой!\". (Аллах) скажет: \"Выведи (из Огня) тех, в чьём сердце была вера весом с ячменное зерно!\". Затем я вновь паду ниц и восхвалю Его восхвалениями, которыми не восхвалял Его никто прежде меня и не восхвалит никто после меня. После этого будет сказано: \"О Мухаммад! Подними голову! Говори, и тебя услышат, проси, и тебе будет даровано, заступайся, и твоё заступничество будет принято!\". Я скажу: \"О Господь мой!\". (Аллах) скажет: \"Выведи (из Огня) тех, в чьём сердце была самая минимальная (вера)\". Тогда из Огня выйдут люди, которых будут называть джаханнамийюн, и они окажутся в Раю».</i></b>"]],[["p","Тут некий человек спросил (Анаса): <i>«О Абу Хамза! Ты слышал это от посланника Аллаха (да благословит его Аллах и приветствует)?». </i>Его лицо изменилось, он разгневался и сказал: <i>«Не всё, что мы рассказываем, мы слышали непосредственно от посланника Аллаха (да благословит его Аллах и приветствует), но мы не считаем лжецами друг друга»</i><sup class=\"fn\">773</sup>."],["n",[[773,"То есть некоторые хадисы мы не слышали непосредственно от пророка (да благословит его Аллах и приветствует), но нам их рассказали другие сподвижники, которые слышали их от пророка (да благословит его Аллах и приветствует), и они не являются лжецами. При этом Анас (да будет доволен им Аллах) слышал этот хадис от пророка (да благословит его Аллах и приветствует), но некоторые его версии он передавал от других сподвижников. Что касается данной версии, то её также передали Ибн Манда в «аль-Иман», 874; Ибн Аби ′Асым в «ас-Сунна», 816."]]],["p","663 ― Хуса ибн ′Убейд передал со слов Анаса ибн Малика (да будет доволен им Аллах), что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Адаму (мир ему) в День Воскресения скажут: \"Заступись за своё потомство\", но он ответит: \"Я не для этого. Отправляйтесь к Нуху, ведь, поистине, он – первый и самый старший из пророков\". Люди придут к Нуху, но он скажет: \"Я не для этого. Вам следует пойти к Ибрахиму, ведь, поистине, Аллах полюбил его сильной любовью\". Люди придут к Ибрахиму, но он скажет: \"Я не для этого. Вам следует пойти к Мусе, ведь, поистине, Аллах говорил с ним без посредников\". Люди придут к Мусе, но он скажет: \"Я не для этого. Вам следует пойти к ′Исе, ведь, поистине, он – дух и слово от Аллаха\". Люди придут к ′Исе, но он скажет: \"Я не для этого, но я укажу вам на того, кто для этого. Ступайте к Мухаммаду (да благословит Аллах и приветствует его и всех пророков)\". </i></b>"],["p","<b><i>Тогда они придут ко мне, и я попрошу разрешения (войти в Рай), и когда я посмотрю на Милостивого, я паду пред Ним ниц, и мне скажут: \"Подними голову, о Мухаммад! Говори, и тебя услышат, проси, заступайся, и твоё заступничество будет принято, проси, и тебе будет даровано\". Тогда я скажу: \"О Господь мой! Моя община!\". Мне скажут: \"Ступайте и не оставляйте в Аду никого, в чьём сердце была вера весом с динар. Обязательно выведите таких!\", и тогда выйдет (из Огня) столько, сколько пожелает Аллах.</i></b>"],["p","<b><i>Затем я паду ниц во второй раз, и мне скажут: \"Подними голову, о Мухаммад! Говори, и тебя услышат, проси, заступайся, и твоё заступничество будет принято, проси, и тебе будет даровано\". Тогда я скажу: \"О Господь мой! Моя община!\". Мне скажут: \"Ступайте и не оставляйте в Аду никого, в чьём сердце была вера весом с половину динара. Обязательно выведите таких!\", и тогда выйдет (из Огня) столько, сколько пожелает Аллах.</i></b>"]],[["p","<b><i>Затем я паду ниц в третий раз, и мне скажут: \"Подними голову, о Мухаммад! Говори, и тебя услышат, проси, заступайся, и твоё заступничество будет принято, проси, и тебе будет даровано\". Тогда я скажу: \"О Господь мой! Моя община!\". Мне скажут: \"Ступайте и не оставляйте в Аду никого, в чьём сердце была вера весом с маленькую букашку. Обязательно выведите таких!\". Тогда (в Аду) останутся только те, в ком нет блага»</i></b><sup class=\"fn\">774</sup>."],["n",[[774,"Данная версия содержит в себе слабость. А Аллах знает лучше!"]]],["p","664 ― Джауса ибн ′Убейд ад-Дияли передал, что слышал, как Анас ибн Малик (да будет доволен им Аллах) говорил: <i>«Когда Всеблагой и Всевышний Аллах рассудит творения и введёт в Рай обитателей Рая, и введёт в Ад обитателей Ада, Мухаммад (да благословит его Аллах и приветствует) падёт ниц и будет долго пребывать в таком положении, после чего провозгласят: \"Подними голову, о Мухаммад! Заступайся, и твоё заступничество будет принято, проси, и тебе будет даровано\". Он поднимет голову и скажет: </i><b><i>\"О Господь мой! Моя община!\". </i></b><i>Всемогущий и Великий Аллах скажет ангелам: \"Выведите для Мухаммада из его общины тех, в чьём сердце была вера весом с кырат\", после чего они выйдут. Затем он падёт ниц во второй раз, и этот земной поклон будет ещё длиннее, чем первый. После этого скажут: \"Подними голову! Заступайся, и твоё заступничество будет принято, проси, и тебе будет даровано\". Он скажет: </i><b><i>\"О Господь мой! Моя община!\". </i></b><i>Всемогущий и Великий Аллах скажет ангелам: \"Выведите из его общины тех, в чьём сердце была вера весом с ячменное зерно\". Затем он падет ниц в третий раз, и этот земной будет ещё длиннее, после чего провозгласят: \"Подними голову! Заступайся, и твоё заступничество будет принято, проси, и тебе будет даровано\". Он скажет: </i><b><i>\"О Господь мой! Моя община!\". </i></b><i>Аллах скажет ангелам: \"Выведите для Мухаммада тех, в чьём сердце была вера весом с горчичное зерно\". Их покажут ему, и (ангелы) выведут их. Они будут уже почерневшими, как сожжённые клинки. Затем они войдут в Рай и обитатели Рая обратятся к ним: \"Кто эти люди, чей запах доставил нам неудобства?!\". Ангелы ответят: \"Это джаханнамиййюн. Их вывели (из Ада) посредством заступничества Мухаммада (да благословит его Аллах и приветствует)\". Затем их отведут к реке жизни, и они искупаются и совершат малое омовение, и примут уже другой облик». </i>"],["p","Передатчик этого хадиса спросил: <i>«О Абу Хамза! Что это за река жизни?». </i>Он ответил: <i>«Одна из райских рек. Она относится к числу нижайших из них»</i><sup class=\"fn\">775</sup><i>. </i>"],["n",[[775,"Данная версия содержит в себе слабость. А Аллах знает лучше!"]]],["p","Передатчик этого хадиса Джауса ибн ′Убейд. ′Аййяш ибн ′Укба аль-Хадрами передавал от него один хадис."]],[["p","665 ― ′Аййяш ибн ′Укба аль-Хадрами слышал, как Джауса ибн ′Убейд ад-Дияли рассказывал от Анаса ибн Малика (да будет доволен им Аллах), который слышал, как посланник Аллаха (да благословит его Аллах и приветствует) говорил: <b><i>«Коран будут читать люди, которым он не проникнет в сердца. Они вылетят из религии, как вылетает стрела, пролетая сквозь мишень»</i></b><sup class=\"fn\">776</sup>."],["n",[[776,"Данная версия содержит в себе слабость, но сам текст хадиса достоверно передан от пророка (да благословит его Аллах и приветствует). Например, его передали аль-Бухари, 5057, Муслим, 1066, и др. со слов ′Али ибн Аби Талиба (да будет доволен им Аллах)."]]],["p","ГЛАВА 72: РАЗЪЯСНЕНИЕ ТОГО, ЧТО МЕСТО, НА КОТОРОМ ПРОРОК (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ) БУДЕТ ЗАСТУПАТЬСЯ ЗА СВОЮ ОБЩИНУ, И ЕСТЬ ТО ДОСТОХВАЛЬНОЕ МЕСТО, КОТОРОЕ ЕМУ ОБЕЩАЛ ВСЕМОГУЩИИ И ВЕЛИКИЙ АЛЛАХ, КОГДА СКАЗАЛ: «БЫТЬ МОЖЕТ, ГОСПОДЬ ТВОЙ ВОЗВЕДЕТ ТЕБЯ НА ДОСТОХВАЛЬНОЕ МЕСТО»<sup class=\"fn\">777</sup>."],["n",[[777,"Сура «аль-Исра», аят 79."]]],["p","Эти слова, по-моему мнению, подобны тому, в отношении чего некоторые учёные сказали: «Когда Аллах говорит: (<span class=\"ar-i\" lang=\"ar\" dir=\"rtl\">عَسَى</span>) (′аса́) [быть может], то это указывает на то, что так случится обязательно».  То есть здесь эти слова не означают сомнение или то, что этого может и не случиться."],["p","666 ― Абу Хурейра (да будет доволен им Аллах) передал, что, разъясняя слова Аллаха: <b>«Быть может, Господь твой возведет тебя на достохвальное место», </b>пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Речь идёт о том месте, где я буду заступаться за свою общину»</i></b><sup class=\"fn\">778</sup>."],["n",[[778,"Ат-Тирмизи, 3137; Ахмад, 2/441; Ибн Аби ′Асым в «ас-Сунна», 784, и др."]]],["p","667 ― Абу Хурейра (да будет доволен им Аллах) рассказывал: <i>«Однажды я спросил посланника Аллаха (да благословит его Аллах и приветствует): \"О посланник Аллаха! Что даровал тебе твой Господь из заступничества?\". Он ответил: </i><b><i>\"Я так и думал, что ты будешь первым, кто спросит меня об этом, ибо видел твоё стремление к знанию. Моё заступничество достанется каждому (члену) моей общины, кто засвидетельствовал, что нет истинного бога, кроме Аллаха, и при этом его сердце подтвердило то, что у него на языке, а язык подтвердил то, что у него в сердце\"</i></b><i>»</i><sup class=\"fn\">779</sup>."],["n",[[779,"Полная версия этого хадиса была приведена под № 641."]]],["p","668 ― Ришди́н ибн Курейб передал от своего отца, что, разъясняя слова Аллаха: <b>«Быть может, Господь твой возведет тебя на достохвальное место», </b>Ибн ′Аббас (да будет доволен Аллах им и его отцом) сказал: <i>«Достохвальное место – это место заступничества (шафа′а)»</i><sup class=\"fn\">780</sup>."],["n",[[780,"Ибн Джарир в «Тафсире», 8/129. Цепочка передатчиков является слабой. А Аллах знает лучше!"]]],["p","669 ― ′Абдуллах ибн ′Умар (да будет доволен Аллах им и его отцом) передал, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Человек будет просить людей</i></b><sup class=\"fn\">781</sup><b><i> до тех пор, пока не придёт в День Воскресения без единого кусочка плоти на лице»</i></b><sup class=\"fn\">782</sup><b><i>.</i></b>"],["n",[[781,"Речь идёт о каждом, кто не имеет на это права, поскольку располагает необходимыми средствами."],[782,"Аль-Бухари, 1474; Муслим, 1040; Ахмад, 2/15, 88; ан-Насаи в «ас-Сунан аль-кубра», 2366; ат-Табарани в «аль-Аусат», 8725, и др."]]]],[["p","670 ― Также пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Поистине, (в День Воскресения) солнце приблизится к людям настолько, что пот дойдёт до середины уха (некоторых из них). И оказавшись в подобном положении, они попросят о помощи Адама, но он скажет: \"Я – не для этого!\". Затем они попросят о помощи Мусу, но он ответит то же самое. Затем они попросят о помощи Мухаммада, и он станет заступаться, дабы (Аллах) провёл суд между творениями. Он пойдёт и схватится за кольцо райских (врат), и вот тогда Аллах возведёт его на достохвальное место. Его будут хвалить все те, кто соберётся в этом месте»</i></b><sup class=\"fn\">783</sup>."],["n",[[783,"Аль-Бухари, 1475; Ибн Манда в «аль-Иман», 884; Ибн Джарир в «Тафсире», 8/129; ат-Табарани в «аль-Аусат», 8725."]]],["p","ГЛАВА 73: УПОМИНАНИЕ ДОВОДА, УКАЗЫВАЮЩЕГО НА ТО, КАК ПРАВИЛЬНО ПОНИМАТЬ ВСЕ ХАДИСЫ О ЗАСТУПНИЧЕСТВЕ ПРОРОКА (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ) ЗА ЕДИНОБОЖНИКОВ В АДУ, КОТОРЫЕ Я ПРИВЁЛ ВЫШЕ. ХОТЬ ОНИ И ЯВЛЯЮТСЯ ОБЩИМИ, НО ИМЕЕТСЯ В НИХ В ВИДУ ЧАСТНОЕ."],["p","В этих хадисах было сказано: <b><i>«Выведите из Огня тех, в чьём сердце была вера весом с то-то и то-то». </i></b>Имеется в виду: выведите некоторых людей, в чьих сердцах была вера (иман) такого размера. Ведь пророк (да благословит его Аллах и приветствует) сообщил, что в этот день будут заступаться и другие, кроме него. То есть Аллах прикажет вывести из Огня некоторых людей по причине заступничества других творений, помимо нашего пророка Мухаммада (да благословит его Аллах и приветствует). Речь идёт о таких людях, в чьих сердцах будет вера того размера, о котором сообщил наш пророк Мухаммад (да благословит его Аллах и приветствует). Но, возможно, что те члены общины Мухаммада (да благословит его Аллах и приветствует), которые будут заступаться, будут заступаться с его позволения. Это приходит в хадисе со слов Адама ибн ′Али от Ибн ′Умара (да будет доволен Аллах им и его отцом). И если пророк (да благословит его Аллах и приветствует) прикажет им заступаться, то это заступничество можно отнести и к нему. Я уже разъяснял в своих книгах, что арабы относят действие к тому, кто его приказал, так же, как они относят его к тому, кто его непосредственно совершил. Религиозные тексты обращаются к нам на арабском языке, а в арабском языке известно, что когда говорят: «Выведи людей из такого-то места», может иметься в виду часть этих людей, а не все они. Человек, который знает арабский язык, не будет отрицать, что под общими словами может иметься в виду частный смысл. Мы разъяснили примеры этого из Книги нашего Господа и Сунны нашего избранного пророка (да благословит его Аллах и приветствует) в книге «Ма’ани аль-Куран» и в наших книгах о фикхе. Даже части этих примеров достаточно для того, кому было оказано содействие в понимании. Поэтому я считаю, что в этих вышеприведённых хадисах о заступничестве пророка (да благословит его Аллах и приветствует) имеется в виду частный смысл. То есть: выведите из Огня тех, в чьём сердце была такая-то вера, но за исключением тех, которые должны выйти по причине заступничества других творений, помимо пророка (да благословит его Аллах и приветствует). Например, по причине заступничества ангелов, правдивых мужей, мучеников и других заступников, которые будут заступаться за своих братьев в религии, которые совершали с ними молитвы, соблюдали с ними пост, совершали с ними хадж<sup class=\"fn\">784</sup>."],["n",[[784,"В чём суть этой главы?! В предыдущих хадисах было сказано: <b><i>«Выведите из Огня тех, в чьём сердце была вера весом с то-то и то-то». </i></b>Автор (да помилует его Аллах) говорит, что это не означает, что в этот момент выведут их всех до единого. Выведут лишь некоторых. Почему он так говорит?! Потому что здесь речь идёт о заступничестве пророка (да благословит его Аллах и приветствует), а после него будут заступаться ещё многие другие творения. Если после его заступничества из Огня выведут абсолютно всех верующих, то за кого тогда будут заступаться другие?! Вот это он имеет в виду."]]]],[["p","671 ― Абу Са′ид аль-Худри (да будет доволен им Аллах) рассказывал: <i>«Однажды мы сказали: \"О посланник Аллаха! Увидим ли мы нашего Господа в День Воскресения?!». </i>Затем он упомянул весь хадис целиком, и в нём среди прочего сказано: <b><i>«После чего над Геенной будет раскинут мост». </i></b>Они спросили: <i>«О посланник Аллаха! А что это за мост? Пусть наши отцы и матери станут выкупом за тебя!». </i>Пророк (да благословит его Аллах и приветствует) сказал: <b><i>«(Это мост, где) скользят и спотыкаются (стопы). На нем есть крюки и шипы, (подобные тем колючкам), которые (растут) в Неджде</i></b><sup class=\"fn\">785</sup><b><i>, и на нем есть колючка, именуемая Са′дан. Верующие будут проходить по этому (мосту) в мгновении ока, или подобно молнии, или подобно ветру, или словно птица, или подобно породистым скакунам, или подобно вьючным верблюдам. Некоторые (из людей) спасутся и будут избавлены (от наказания Аллаха), другие – будут оцарапаны (этими крюками), но затем отпущены, (чтобы идти дальше), а третьи – свалятся в огонь Геенны.</i></b>"],["n",[[785,"Все возвышенные районы от Тихамы до Ирака называются Недждом. См. «Аль-Мисбах уль-мунир», 2/593."]]],["p","<b><i>Клянусь Тем, в Чьей руке моя душа! Вы не просите у меня (именем Аллаха) столь сильно (осуществления) истины, которая стала явной для вас, как (в Тот День) верующие, спасшиеся от Огня, (будут просить у Аллаха) за своих братьев, (попавших в Огонь). Они скажут: \"О Господь наш! Наши братья совершали молитвы вместе с нами, отправлялись в хадж вместе с нами, усердствовали (на пути Аллаха) вместе с нами, соблюдали пост вместе с нами, но их схватил Огонь!\". Аллах скажет им: \"Ступайте и выведите тех, чей облик вы узнаете!\", и их тела (с этого момента) будут защищены от Огня. Некоторых людей Огонь уже охватит до стоп, некоторых – до середины голени, некоторых – до колен, некоторых – до пояса. И вот так они выведут из Огня множество людей. Затем они вернутся и (вновь) начнут говорить, и (Аллах) скажет: \"Ступайте и выведите тех, в чьём сердце вы обнаружите благо весом с кырат\", и они выведут из Огня множество людей. Затем они вернутся и (вновь) начнут говорить, и (Аллах) скажет: \"Ступайте и выведите тех, в чьём сердце вы обнаружите благо весом с половину кырата\", и они выведут из Огня множество людей. Затем они вернутся и (вновь) начнут говорить, и Аллах будет отвечать им так же, пока не скажет: \"Ступайте и выведите тех, в чьём сердце вы обнаружите благо весом с маленького муравья\"»</i></b><sup class=\"fn\">786</sup>."],["n",[[786,"Абу Са′ид аль-Худри говорил: <i>«Если вы не верите мне относительно этого хадиса, то читайте (слова Аллаха), если пожелаете:</i> <b>\"Поистине, Аллах не поступает несправедливо даже на вес маленького муравья! И если будет (у человека) какое-нибудь благое деяние, Он умножит его и дарует от Себя великую награду\"</b>»."]]]],[["p","Затем в хадисе пришло: <b><i>«Они скажут: \"Господь наш! Мы не оставили там тех, в ком есть благо!\". (Аллах) скажет: \"Остался ли кто-то, кроме самого милостивого из всех милостивых? Уже заступились ангелы, заступились пророки, заступились верующие. Остался ли кто-то, кроме самого милостивого из всех милостивых?\". И тогда Он возьмет из Огня горсть и выведет (из Огня) группу (людей), которые никогда не совершали ради Него ничего благого и уже превратились в пепел. Их бросят в реку, именуемую рекой жизни, и они вырастут в ней. Клянусь Тем, в Чьей руке моя душа! Так же, как вырастают семена, несомые водным потоком»</i></b><sup class=\"fn\">787</sup><b><i>. </i></b>"],["n",[[787,"Аль-Бухари, 7439; Муслим, 183; Ибн Аби ′Асым в «ас-Сунна», 635; аль-Хаким в «аль-Мустадрак», 8736; Ибн Джарир в «Тафсире», 12/197."]]],["p","672 ― [Под этим номером приведено то же самое сообщение, что и под № 671]."],["p","Что касается слов <b><i>«…никогда не совершали ничего благого…», </i></b>то относительно таких выражений арабы говорят, что речь идёт об отрицании какой-то вещи из-за того, что она является неполноценной и несовершенной. В соответствии с этим смыслом даннные слова означают: никогда не совершали ничего благого в полноценном и совершенном виде. Я разъяснял этот смысл во многих своих книгах."],["p","673 ― [Под этим номером приведено то же самое сообщение, что и под № 671]."],["p","674 ― [Под этим номером приведено то же самое сообщение, что и под № 671]."],["p","ГЛАВА 74: РАЗЪЯСНЕНИЕ ТОГО, ЧТО ПРАВДИВЕЙШИЕ МУЖИ БУДУТ ЗАСТУПАТЬСЯ ПОСЛЕ ПРОРОКА (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ) В ДЕНЬ ВОСКРЕСЕНИЯ. ЗАТЕМ ПОСЛЕ ПРАВДИВЕЙШИХ МУЖЕЙ БУДУТ ЗАСТУПАТЬСЯ ДРУГИЕ ПРОРОКИ (МИР ИМ ВСЕМ И БЛАГОСЛОВЕНИЕ АЛЛАХА). ЗАТЕМ ЗА ПРОРОКАМИ (МИР ИМ) ПОСЛЕДУЮТ МУЧЕНИКИ. ЕСЛИ КОНЕЧНО ЭТОТ ХАДИС ДОСТОВЕРЕН."],["p","675 ― Абу Бакр ас-Сыддик (да будет доволен им Аллах) рассказывал: <i>«Однажды утром посланник Аллаха (да благословит его Аллах и приветствует) совершил утреннюю молитву, после чего сел, а когда солнце взошло на достаточную высоту, он засмеялся. Он продолжил сидеть на своем месте, пока не совершил обеденную (зухр), послеобеденную (′аср) и вечернюю (магриб) молитвы, и все это время он не разговаривал, после чего совершил последнюю ночную молитву (′иша), а затем направился к своей семье». </i>"],["p","(Передатчик этого хадиса рассказывал):<i> «Тогда люди сказали Абу Бакру (да будет доволен им Аллах): \"Спроси у посланника Аллаха (да благословит его Аллах и приветствует), почему сегодня он вел себя так, как никогда прежде!\". (А когда посланника Аллаха (да благословит его Аллах и приветствует) спросили об этом), он ответил:</i> <b><i>«Мне было показано все, что произойдет из дел ближней жизни и Последней обители. Первые и последние (поколения) будут собраны в одном месте, и из-за этого их охватит ужас, и тогда они направятся к (пророку) Адаму, когда (их) пот уже вот-вот дойдет до их ртов. Они скажут: \"О Адам! Ты – праотец человечества, и Аллах избрал тебя! Заступись же за нас пред своим Господом!\", (но Адам) ответит: \"Поистине, я претерпеваю то же, что и вы!</i></b><sup class=\"fn\">788</sup> <b><i>Ступайте к вашему следующему праотцу – (пророку) Нуху!\". </i></b>"],["n",[[788,"То есть для меня этот день так же суров и долог, как и для вас. Возможен также и следующий перевод его фразы: «Поистине, я так же совершил (в ближней жизни) грехи, как и вы!». См. «Хашия Муснад Ахмад», 1/33-34, Абу-ль Хасана ас-Синди."]]]],[["p","<b><i>(Аллах сказал):</i> \"Поистине, Аллах избрал из миров Адама, Нуха, семейство Ибрахима и семейство ′Имрана\"</b><sup class=\"fn\">789</sup>."],["n",[[789,"Сура «Али ′Имран», аят 33."]]],["p","<b><i>Тогда (люди) отправятся к Нуху и скажут (ему): \"Заступись за нас пред своим Господом, ибо, поистине, Аллах избрал тебя и ответил на твою мольбу, не оставив на земле ни одного неверующего обитателя!\", но он ответит: \"У меня нет такой (возможности)! Ступайте к (пророку) Ибрахиму, ибо, поистине, Аллах полюбил Его сильной любовью!\".</i></b>"],["p","<b><i>Тогда (люди) отправятся к Ибрахиму (с этой просьбой), но он ответит им: \"У меня нет такой (возможности)! Ступайте к (пророку) Мусе, ибо, поистине, Аллах вел с ним беседу!\".</i></b>"],["p","<b><i>Тогда (люди) отправятся к Мусе (с этой просьбой), но он ответит им: \"У меня нет такой (возможности)! Ступайте к (пророку) ′Исе, сыну Марьям, ведь, поистине, он исцелял слепых и больных проказой, и возвращал к жизни мертвых (с соизволения Аллаха)!\". (Когда же они придут к ′Исе), он ответит (им): \"У меня нет такой (возможности)! Ступайте к господину потомков Адама, ведь, поистине, он был первым, над кем разверзлась земля в День Воскресения! Ступайте к Мухаммаду, и пусть он заступится за вас пред вашим Господом!\".  </i></b>"],["p","<b><i>Тогда они направятся ко мне, а я подойду к Джибрилю, который подойдет к своему Господу, Который скажет: «Позволь ему (заступаться) и обрадуй его вестью о Рае!». </i></b>"],["p","(Передатчик этого хадиса рассказывал): <i>«Тогда Джибриль подойдет с пророком к Аллаху, и (пророк) падет ниц и проведет в таком положении целую неделю, после чего Аллах скажет: </i><b><i>\"О Мухаммад! Подними свою голову! Говори и ты будешь услышан, заступайся и твое заступничество будет принято!\"</i></b><i>. Тогда (пророк (да благословит его Аллах и приветствует)) поднимет свою голову, а когда он увидит своего Господа, то (вновь) падет ниц и проведет в таком положении (еще) целую неделю, после чего (Аллах) скажет: </i><b><i>\"О Мухаммад! Подними свою голову! Говори и ты будешь услышан, заступайся и твое заступничество будет принято!\"</i></b><i>. Тогда он подойдет (ближе), чтобы (вновь) пасть ниц, а Джибриль схватит его за руки, и Аллах откроет ему такие мольбы, которые никогда прежде не открывал ни одному человеку. (Пророк (да благословит его Аллах и приветствует)) скажет: </i><b><i>\"О Господь мой! Ты сделал меня господином потомков Адама, но я не бахвалюсь этим! И (Ты сделал меня) первым, над кем разверзлась земля в День Воскресения, но я не бахвалюсь этим!\"</i></b><i>.</i>"],["p","(Далее пророк (да благословит его Аллах и приветствует) рассказывал): <b><i>«Поистине, ко мне у (моего) водоема подойдет большее количество людей, чем (расстояние) между Саной и Айлей, а затем возгласят: \"Призовите правдивейших, чтобы они заступались!\". Затем возгласят: \"Призовите пророков!\", и придет пророк, с которым будет группа людей, и придет пророк, с которым будет пять или шесть человек, и придет пророк, с которым не будет никого. Затем возгласят: \"Призовите мучеников!\", после чего они начнут заступаться за тех, за кого пожелают. Когда же мученики закончат (заступаться), Всеблагой и Всевышний Аллах скажет: \"Я – Самый милостивый из всех милостивых! Введите в Мой Рай всех тех, кто ничего не придавал Мне в сотоварищи!\", после чего (эти люди) войдут в Рай. Затем Всеблагой и Всевышний Аллах скажет: \"Посмотрите в Огонь, есть ли в нем кто-нибудь, кто хоть когда-нибудь совершал нечто благое?\". И (ангелы) обнаружат в Огне человека, которому скажут: \"Совершал ли ты когда-нибудь что-нибудь благое?\". Он ответит: \"Нет, за исключением того, что я снисходительно относился к людям во время торговли!\". Всемогущий и Великий Аллах скажет: \"Проявите снисходительность к Моему рабу, как он проявлял снисходительность к (другим) Моим рабам!\". Затем из Огня выведут другого (человека) и спросят у него: \"Совершал ли ты когда-нибудь что-нибудь благое?\". Он ответит: «Нет, за исключением того, что я повелел своим детям: \"Когда я умру, сожгите мое (тело) в Огне, а затем измельчите мой (прах), а когда мой (прах) превратится в порошок, то отнесите его к морю и развейте по ветру!\"». Аллах спросит (у него): \"Зачем же ты поступил так?\". (Человек) ответит: \"Из-за страха пред Тобой!\". Тогда Всевышний (Аллах) скажет: \"Взгляни на владения величайшего царя (в ближней жизни)! Поистине, тебе то же самое и еще в десять раз больше!\". Тогда (этот человек) воскликнет: \"Зачем Ты издеваешься надо мной в то время, как Ты являешься (истинным) Царем?!\". И именно по этой причине я засмеялся утром!»</i></b><sup class=\"fn\">790</sup>."],["n",[[790,"Ахмад, 1/4; Ибн Хиббан, 6476; Абу Я′ля, 56, 57; аль-Баззар, 76, и др. Аль-Альбани назвал хадис хорошим (хасан) в «Сахих ат-Таргыб», 3641. А Аллах знает лучше!"]]]],[["p","Я оговорился, что этот хадис может быть недостоверным, так как в тот момент, когда я записывал название главы, я не помнил ещё какой-то хадис, переданный Валяном<sup class=\"fn\">791</sup>, кроме этого. Однако от него передавал Малик ибн ′Умейр аль-Ханафи, но при этом он назвал его «аль-′Иджли», а не «аль-′Адауи»."],["n",[[791,"Один из передатчиков вышеприведенного хадиса."]]],["p","676 ― Малик ибн ′Умейр аль-Ханафи передал, что Валян аль-′Иджли рассказывал: <i>«Однажды я возвращался домой и увидел, что мою овечку, дающую молоко, кто-то порезал. Вокруг неё стояли женщины, и я спросил: \"Что с ней стало?\". Они сказали: \"Она заболела\".  Я спросил: \"Кто порезал её?\". Они ответили: \"Этот твой слуга\". Клянусь Аллахом, он не умел правильно совершать молитву и правильно обращаться с мольбами. Он был из числа пленных невольников. Но (люди) сказали: \"Мы научили его, (как резать). И он произнёс имя Аллаха\". Я не стал слезать со своей мулицы и отправился к ′Абдуллаху (ибн Мас′уду), рассказал ему эту историю, и он сказал: \"Ешь её (мясо)\"»</i><sup class=\"fn\">792</sup>."],["n",[[792,"Это сообщение является слабым, так как положение Малика ибн ′Умейра аль-Ханафи неизвестно. Ибн Хузейма (да помилует его Аллах), приводя это сообщение, хотел утвердить, что от Валяна передают сообщения разные передатчики, и что он не является неизвестной личностью. При этом здесь речь не идёт про Валяна аль-′Адауи, от которого передан предыдущий хадис. Здесь говорится о Валяне аль-′Иджли, а это – другой человек. В любом случае, как уже было сказано, предыдущий хадис является хорошим (хасан). А Аллах знает лучше!"]]],["p","ГЛАВА 75: ОГРОМНОЕ КОЛИЧЕСТВО ТЕХ, ЗА КОГО БУДЕТ ЗАСТУПАТЬСЯ ОДИН ЧЕЛОВЕК ИЗ ЭТОЙ ОБЩИНЫ. К ТОМУ ЖЕ В ЭТОЙ ГЛАВЕ УПОМИНАЕТСЯ ДОВОД, УКАЗЫВАЮЩИЙ НА ПРАВИЛЬНОСТЬ ТОГО, О ЧЁМ Я ГОВОРИЛ РАНЕЕ, ЗАМЕТИВ, ЧТО В ДЕНЬ ВОСКРЕСЕНИЯ БУДУТ ЗАСТУПАТЬСЯ НЕ ТОЛЬКО ПРОРОКИ (МИР ИМ)"],["p","677 ― ′Абдуллах ибн Шакы́к рассказывал: <i>«Однажды я сидел с (тремя) людьми, с коими я был четвертым. Один из них сказал: «Я слышал, как посланник Аллаха (да благословит его Аллах и приветствует) говорил: </i><b><i>\"(В День Воскресения) по причине заступничества одного мужа из моей общины в Рай войдет (так много людей, что их количество) будет больше, чем (людей в) племени бану тамим\"</i></b><i>. (Услышав это), мы спросили: \"О посланник Аллаха! (Ты имеешь в виду себя или) кого-то другого?\". (Пророк, да благословит его Аллах и приветствует), ответил: </i><b><i>\"(Я имею в виду) другого (человека), а не себя!\"</i></b><i>».</i>"],["p","(′Абдуллах ибн Шакы́к продолжил): <i>«Я спросил: \"Ты (действительно) слышал это от посланника Аллаха (да благословит его Аллах и приветствует)?\". (Этот человек) ответил: \"Да!\". Когда же он встал (и удалился), я спросил (у присутствующих): \"Кто этот (человек)?\". Они ответили: \"Ибн Аби-ль Джад′а\"»</i><sup class=\"fn\">793</sup>."],["n",[[793,"Ат-Тирмизи, 2438; Ибн Маджа, 4316; Ахмад, 3/469; ад-Дарими, 2808; Ибн Хиббан, 7376, и др."]]]]];
